CREATE TABLE org_roles(user_id INTEGER NOT NULL REFERENCES users(id),role TEXT NOT NULL CHECK(role IN('hr','payroll','auditor','integration')),PRIMARY KEY(user_id,role));
CREATE TABLE controls(name TEXT PRIMARY KEY,value TEXT NOT NULL,actor_id INTEGER REFERENCES users(id));
INSERT INTO controls(name,value) VALUES('require_vouchers','false'),('notifications_enabled','true'),('mfa_required','false');
CREATE TABLE work_policies(kind TEXT PRIMARY KEY,rules TEXT NOT NULL);
INSERT INTO work_policies(kind,rules) VALUES('payment','[{"min":0,"max":null,"levels":[["manager"]]}]'),('journal','[{"min":0,"max":null,"levels":[["manager"]]}]'),('payroll','[{"min":0,"max":null,"levels":[["payroll"]]}]');
CREATE TABLE delegations(id INTEGER PRIMARY KEY,project_id INTEGER NOT NULL REFERENCES projects(id),principal_id INTEGER NOT NULL REFERENCES users(id),delegate_id INTEGER NOT NULL REFERENCES users(id),role TEXT NOT NULL CHECK(role IN('manager','finance')),start_date TEXT NOT NULL,end_date TEXT NOT NULL,reason TEXT NOT NULL,actor_id INTEGER NOT NULL REFERENCES users(id),CHECK(principal_id<>delegate_id),CHECK(start_date<=end_date));
CREATE TABLE delegation_revocations(delegation_id INTEGER PRIMARY KEY REFERENCES delegations(id),reason TEXT NOT NULL,actor_id INTEGER NOT NULL REFERENCES users(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
ALTER TABLE approvals ADD COLUMN principal_id INTEGER REFERENCES users(id);
ALTER TABLE approvals ADD COLUMN delegation_id INTEGER REFERENCES delegations(id);
CREATE TABLE comments(id INTEGER PRIMARY KEY,project_id INTEGER NOT NULL REFERENCES projects(id),kind TEXT NOT NULL,entity_id INTEGER NOT NULL,location TEXT NOT NULL,body TEXT NOT NULL,parent_id INTEGER REFERENCES comments(id),actor_id INTEGER NOT NULL REFERENCES users(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE comment_events(id INTEGER PRIMARY KEY,comment_id INTEGER NOT NULL REFERENCES comments(id),kind TEXT NOT NULL CHECK(kind IN('resolve','reopen')),reason TEXT NOT NULL,actor_id INTEGER NOT NULL REFERENCES users(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE notifications(id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),project_id INTEGER REFERENCES projects(id),kind TEXT NOT NULL,entity_id INTEGER NOT NULL,title TEXT NOT NULL,body TEXT NOT NULL,dedupe TEXT NOT NULL UNIQUE,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE notification_reads(notification_id INTEGER NOT NULL REFERENCES notifications(id),user_id INTEGER NOT NULL REFERENCES users(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(notification_id,user_id));
CREATE TABLE deliveries(id INTEGER PRIMARY KEY,notification_id INTEGER NOT NULL UNIQUE REFERENCES notifications(id),channel TEXT NOT NULL,recipient TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'queued' CHECK(state IN('queued','sending','sent','failed')),attempts INTEGER NOT NULL DEFAULT 0,next_attempt INTEGER NOT NULL DEFAULT 0,lease_until INTEGER NOT NULL DEFAULT 0,last_error TEXT NOT NULL DEFAULT '',sent_at TEXT);
CREATE TABLE request_modes(request_id INTEGER PRIMARY KEY REFERENCES requests(id),mode TEXT NOT NULL CHECK(mode IN('expense','payroll')));
CREATE TABLE expenses(id INTEGER PRIMARY KEY,request_id INTEGER NOT NULL REFERENCES requests(id),reference TEXT NOT NULL UNIQUE,payee TEXT NOT NULL,due_date TEXT NOT NULL,journal_id INTEGER NOT NULL UNIQUE REFERENCES journals(id),date TEXT NOT NULL);
CREATE TABLE expense_lines(id INTEGER PRIMARY KEY,expense_id INTEGER NOT NULL REFERENCES expenses(id),request_line_id INTEGER NOT NULL REFERENCES request_lines(id),amount INTEGER NOT NULL CHECK(amount>0));
CREATE TABLE vouchers(id INTEGER PRIMARY KEY,target_kind TEXT NOT NULL CHECK(target_kind IN('bill','expense','payroll_net','payroll_tax')),target_id INTEGER NOT NULL,account_id INTEGER NOT NULL REFERENCES accounts(id),amount INTEGER NOT NULL CHECK(amount>0),reference TEXT NOT NULL, date TEXT NOT NULL,creator_id INTEGER NOT NULL REFERENCES users(id),approval_policy TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(account_id,reference));
CREATE TABLE work_approvals(id INTEGER PRIMARY KEY,kind TEXT NOT NULL,document_id INTEGER NOT NULL,level INTEGER NOT NULL,actor_id INTEGER NOT NULL REFERENCES users(id),principal_id INTEGER REFERENCES users(id),delegation_id INTEGER REFERENCES delegations(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(kind,document_id,level));
CREATE TABLE voucher_posts(voucher_id INTEGER PRIMARY KEY REFERENCES vouchers(id),journal_id INTEGER NOT NULL UNIQUE REFERENCES journals(id));
CREATE TABLE voucher_cancellations(voucher_id INTEGER PRIMARY KEY REFERENCES vouchers(id),actor_id INTEGER NOT NULL REFERENCES users(id),reason TEXT NOT NULL);
CREATE TABLE voucher_allocations(id INTEGER PRIMARY KEY,voucher_id INTEGER NOT NULL REFERENCES vouchers(id),project_id INTEGER NOT NULL REFERENCES projects(id),source_id INTEGER NOT NULL REFERENCES funding_sources(id),allocation_id INTEGER NOT NULL,amount INTEGER NOT NULL CHECK(amount>0));
CREATE TABLE expense_payments(id INTEGER PRIMARY KEY,expense_id INTEGER NOT NULL REFERENCES expenses(id),journal_id INTEGER NOT NULL UNIQUE REFERENCES journals(id),amount INTEGER NOT NULL CHECK(amount>0));
CREATE TABLE expense_payment_lines(payment_id INTEGER NOT NULL REFERENCES expense_payments(id),expense_line_id INTEGER NOT NULL REFERENCES expense_lines(id),amount INTEGER NOT NULL CHECK(amount>0),PRIMARY KEY(payment_id,expense_line_id));
CREATE TABLE journal_proposals(id INTEGER PRIMARY KEY,original_id INTEGER NOT NULL REFERENCES journals(id),reference TEXT NOT NULL UNIQUE,date TEXT NOT NULL,reason TEXT NOT NULL,creator_id INTEGER NOT NULL REFERENCES users(id),approval_policy TEXT NOT NULL,lines TEXT NOT NULL,charges TEXT NOT NULL,authorization_id INTEGER REFERENCES correction_authorizations(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE journal_proposal_posts(proposal_id INTEGER PRIMARY KEY REFERENCES journal_proposals(id),journal_id INTEGER NOT NULL UNIQUE REFERENCES journals(id));
CREATE TABLE bill_reissues(new_bill_id INTEGER PRIMARY KEY REFERENCES bills(id),original_bill_id INTEGER NOT NULL UNIQUE REFERENCES bills(id),canonical_invoice TEXT NOT NULL,reason TEXT NOT NULL);
CREATE TABLE grant_versions(id INTEGER PRIMARY KEY,source_id INTEGER NOT NULL REFERENCES funding_sources(id),previous_id INTEGER REFERENCES grant_versions(id),amount INTEGER NOT NULL CHECK(amount>=0),reason TEXT NOT NULL,creator_id INTEGER NOT NULL REFERENCES users(id),approval_policy TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE grant_activations(grant_id INTEGER PRIMARY KEY REFERENCES grant_versions(id),actor_id INTEGER NOT NULL REFERENCES users(id));
CREATE TABLE currency_definitions(code TEXT PRIMARY KEY,scale INTEGER NOT NULL CHECK(scale BETWEEN 0 AND 4));
INSERT INTO currency_definitions(code,scale) VALUES('USD',2);
CREATE TABLE fx_rates(id INTEGER PRIMARY KEY,currency TEXT NOT NULL REFERENCES currency_definitions(code),date TEXT NOT NULL,numerator TEXT NOT NULL,denominator TEXT NOT NULL,reference TEXT NOT NULL UNIQUE,reason TEXT NOT NULL,actor_id INTEGER NOT NULL REFERENCES users(id));
CREATE TABLE foreign_documents(id INTEGER PRIMARY KEY,kind TEXT NOT NULL,entity_id INTEGER NOT NULL,currency TEXT NOT NULL REFERENCES currency_definitions(code),units INTEGER NOT NULL,rate_id INTEGER NOT NULL REFERENCES fx_rates(id),base_amount INTEGER NOT NULL,rounding TEXT NOT NULL,UNIQUE(kind,entity_id));
CREATE TABLE account_currencies(account_id INTEGER PRIMARY KEY REFERENCES accounts(id),currency TEXT NOT NULL REFERENCES currency_definitions(code));
CREATE TABLE foreign_cash_lines(id INTEGER PRIMARY KEY,journal_line_id INTEGER NOT NULL UNIQUE REFERENCES journal_lines(id),currency TEXT NOT NULL REFERENCES currency_definitions(code),units INTEGER NOT NULL,rate_id INTEGER NOT NULL REFERENCES fx_rates(id));
CREATE TABLE employees(id INTEGER PRIMARY KEY,code TEXT NOT NULL UNIQUE,name TEXT NOT NULL,user_id INTEGER UNIQUE REFERENCES users(id),department TEXT NOT NULL,start_date TEXT NOT NULL,terms_encrypted TEXT NOT NULL,actor_id INTEGER NOT NULL REFERENCES users(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE employee_events(id INTEGER PRIMARY KEY,employee_id INTEGER NOT NULL REFERENCES employees(id),kind TEXT NOT NULL CHECK(kind IN('active','inactive')),reason TEXT NOT NULL,actor_id INTEGER NOT NULL REFERENCES users(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE attendance(id INTEGER PRIMARY KEY,employee_id INTEGER NOT NULL REFERENCES employees(id),date TEXT NOT NULL,minutes INTEGER NOT NULL CHECK(minutes BETWEEN 0 AND 1440),reason TEXT NOT NULL,previous_id INTEGER REFERENCES attendance(id),actor_id INTEGER NOT NULL REFERENCES users(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE leave_requests(id INTEGER PRIMARY KEY,employee_id INTEGER NOT NULL REFERENCES employees(id),start_date TEXT NOT NULL,end_date TEXT NOT NULL,type TEXT NOT NULL,reason TEXT NOT NULL,creator_id INTEGER NOT NULL REFERENCES users(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,CHECK(start_date<=end_date));
CREATE TABLE leave_decisions(leave_id INTEGER PRIMARY KEY REFERENCES leave_requests(id),decision TEXT NOT NULL CHECK(decision IN('approved','rejected')),reason TEXT NOT NULL,actor_id INTEGER NOT NULL REFERENCES users(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE payroll_rules(id INTEGER PRIMARY KEY,jurisdiction TEXT NOT NULL,start_date TEXT NOT NULL,end_date TEXT NOT NULL,rules TEXT NOT NULL,reason TEXT NOT NULL,creator_id INTEGER NOT NULL REFERENCES users(id),demo INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,CHECK(start_date<=end_date));
CREATE TABLE payroll_rule_approvals(rule_id INTEGER PRIMARY KEY REFERENCES payroll_rules(id),actor_id INTEGER NOT NULL REFERENCES users(id));
CREATE TABLE payroll_runs(id INTEGER PRIMARY KEY,reference TEXT NOT NULL UNIQUE,period TEXT NOT NULL,date TEXT NOT NULL,rule_id INTEGER NOT NULL REFERENCES payroll_rules(id),creator_id INTEGER NOT NULL REFERENCES users(id),approval_policy TEXT NOT NULL,results_encrypted TEXT NOT NULL,replaces_id INTEGER UNIQUE REFERENCES payroll_runs(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE payroll_allocations(id INTEGER PRIMARY KEY,run_id INTEGER NOT NULL REFERENCES payroll_runs(id),employee_id INTEGER NOT NULL REFERENCES employees(id),project_id INTEGER NOT NULL REFERENCES projects(id),source_id INTEGER NOT NULL REFERENCES funding_sources(id),category TEXT NOT NULL,activity TEXT NOT NULL,amount INTEGER NOT NULL CHECK(amount>0),net INTEGER NOT NULL CHECK(net>=0),tax INTEGER NOT NULL CHECK(tax>=0),CHECK(amount=net+tax));
CREATE TABLE payroll_reservations(run_id INTEGER PRIMARY KEY REFERENCES payroll_runs(id),request_id INTEGER NOT NULL UNIQUE REFERENCES requests(id));
CREATE TABLE payroll_posts(run_id INTEGER PRIMARY KEY REFERENCES payroll_runs(id),journal_id INTEGER NOT NULL UNIQUE REFERENCES journals(id));
CREATE TABLE payroll_payments(id INTEGER PRIMARY KEY,run_id INTEGER NOT NULL REFERENCES payroll_runs(id),kind TEXT NOT NULL CHECK(kind IN('net','tax')),journal_id INTEGER NOT NULL UNIQUE REFERENCES journals(id),amount INTEGER NOT NULL CHECK(amount>0));
CREATE TABLE payroll_payment_lines(payment_id INTEGER NOT NULL REFERENCES payroll_payments(id),allocation_id INTEGER NOT NULL REFERENCES payroll_allocations(id),amount INTEGER NOT NULL CHECK(amount>0),PRIMARY KEY(payment_id,allocation_id));
CREATE TABLE integrations(id INTEGER PRIMARY KEY,name TEXT NOT NULL UNIQUE,endpoint TEXT NOT NULL,secret_encrypted TEXT NOT NULL,enabled INTEGER NOT NULL CHECK(enabled IN(0,1)),actor_id INTEGER NOT NULL REFERENCES users(id));
CREATE TABLE integration_outbox(id INTEGER PRIMARY KEY,integration_id INTEGER NOT NULL REFERENCES integrations(id),event_key TEXT NOT NULL,payload TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'queued',attempts INTEGER NOT NULL DEFAULT 0,lease_until INTEGER NOT NULL DEFAULT 0,next_attempt INTEGER NOT NULL DEFAULT 0,last_error TEXT NOT NULL DEFAULT '',delivered_at TEXT,UNIQUE(integration_id,event_key));
CREATE TABLE integration_routes(integration_id INTEGER NOT NULL REFERENCES integrations(id),external_source TEXT NOT NULL,source_id INTEGER NOT NULL REFERENCES funding_sources(id),account_id INTEGER NOT NULL REFERENCES accounts(id),poster_id INTEGER NOT NULL REFERENCES users(id),PRIMARY KEY(integration_id,external_source));
CREATE TABLE integration_events(integration_id INTEGER NOT NULL REFERENCES integrations(id),external_id TEXT NOT NULL,payload_hash TEXT NOT NULL,result TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(integration_id,external_id));
CREATE TABLE user_mfa(user_id INTEGER PRIMARY KEY REFERENCES users(id),secret_encrypted TEXT NOT NULL,enabled INTEGER NOT NULL DEFAULT 0 CHECK(enabled IN(0,1)));
CREATE TABLE mfa_consumptions(user_id INTEGER NOT NULL REFERENCES users(id),counter INTEGER NOT NULL,PRIMARY KEY(user_id,counter));
CREATE TABLE mfa_recovery(user_id INTEGER NOT NULL REFERENCES users(id),code_hash TEXT PRIMARY KEY,consumed INTEGER NOT NULL DEFAULT 0 CHECK(consumed IN(0,1)));
CREATE TABLE oidc_attempts(token_hash TEXT PRIMARY KEY,payload_encrypted TEXT NOT NULL,expires INTEGER NOT NULL,used INTEGER NOT NULL DEFAULT 0,user_id INTEGER REFERENCES users(id),verified INTEGER NOT NULL DEFAULT 0);
CREATE TABLE oidc_identities(issuer TEXT NOT NULL,subject TEXT NOT NULL,user_id INTEGER NOT NULL REFERENCES users(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(issuer,subject),UNIQUE(issuer,user_id));
CREATE TABLE suppliers(id INTEGER PRIMARY KEY,code TEXT NOT NULL UNIQUE,name TEXT NOT NULL UNIQUE,contact TEXT NOT NULL,actor_id INTEGER NOT NULL REFERENCES users(id));
CREATE TABLE supplier_events(id INTEGER PRIMARY KEY,supplier_id INTEGER NOT NULL REFERENCES suppliers(id),kind TEXT NOT NULL CHECK(kind IN('active','inactive')),reason TEXT NOT NULL,actor_id INTEGER NOT NULL REFERENCES users(id));
CREATE TABLE items(id INTEGER PRIMARY KEY,code TEXT NOT NULL UNIQUE,name TEXT NOT NULL,unit TEXT NOT NULL,category TEXT NOT NULL,actor_id INTEGER NOT NULL REFERENCES users(id));
CREATE TABLE po_suppliers(po_id INTEGER PRIMARY KEY REFERENCES purchase_orders(id),supplier_id INTEGER NOT NULL REFERENCES suppliers(id));
INSERT INTO accounts(code,name,type) VALUES('2100','Net payroll payable','payable'),('2110','Statutory payroll payable','payable'),('5100','Payroll expenditure','expense'),('5200','Realized exchange gain/loss','expense');
CREATE INDEX notification_recipient ON notifications(user_id,id);
CREATE INDEX payroll_employee_period ON payroll_allocations(employee_id,run_id);
CREATE INDEX invoice_reissue_chain ON bill_reissues(original_bill_id,new_bill_id);
